# ---------- claude_usage/scan.py ----------

"""Find setup-tokens and Claude config dirs written in shell, PowerShell and cmd files."""


import os
import re
from typing import List, Optional, Tuple

TOKEN_RE = re.compile(r"sk-ant-oat\d+-[A-Za-z0-9_-]+")
TOKEN_VAR = "CLAUDE_CODE_OAUTH_TOKEN"
CONFIG_DIR_VAR = "CLAUDE_CONFIG_DIR"
# Value read from a file: bash `$(cat FILE)`, PowerShell `Get-Content FILE` / `gc FILE`.
CAT_RE = re.compile(r"\$\(\s*cat\s+([^)]+?)\s*\)")
GET_CONTENT_RE = re.compile(r"\b(?:Get-Content|gc)\s+(?:-Raw\s+)?(?:-Path\s+)?([\"']?)([^\"'\s;)]+)\1",
                            re.I)
# The name a line gives its command: bash alias, PowerShell function, cmd doskey macro.
NAME_RES = [
    re.compile(r"^\s*alias\s+([\w.-]+)="),
    re.compile(r"^\s*function\s+([\w.-]+)", re.I),
    re.compile(r"^\s*doskey\s+([\w.-]+)=", re.I),
]
COMMENT_PREFIXES = ("#", "::", "rem ", "REM ")
MAX_SCAN_BYTES = 256 * 1024


def expand_path(path: str, home: str) -> str:
    """Expand ~, $HOME, ${HOME}, $env:USERPROFILE and %USERPROFILE% against `home`."""
    path = path.strip().strip("'\"")
    for var in ("${HOME}", "$HOME", "$env:USERPROFILE", "$env:HOME", "%USERPROFILE%", "%HOME%"):
        path = path.replace(var, home)
    if path == "~" or path.startswith("~/") or path.startswith("~\\"):
        path = home + path[1:]
    return path


def token_in_text(text: Optional[str]) -> Optional[str]:
    m = TOKEN_RE.search(text or "")
    return m.group(0) if m else None


def read_token_file(path: str) -> Optional[str]:
    try:
        with open(path, encoding="utf-8", errors="ignore") as f:
            return token_in_text(f.read())
    except OSError:
        return None


class ShellScanner:
    """Reads tokens and config dirs from the text of a script or profile file."""

    def __init__(self, home: str):
        self.home = home

    def token_from_value(self, value: str) -> Optional[str]:
        """Resolve what follows CLAUDE_CODE_OAUTH_TOKEN on a line to a token."""
        token = token_in_text(value)
        if token:
            return token
        m = CAT_RE.search(value)
        if m:
            return read_token_file(expand_path(m.group(1), self.home))
        m = GET_CONTENT_RE.search(value)
        if m:
            return read_token_file(expand_path(m.group(2), self.home))
        return None

    def lines(self, path: str) -> List[str]:
        try:
            if os.path.getsize(path) > MAX_SCAN_BYTES:
                return []
            with open(path, encoding="utf-8", errors="ignore") as f:
                return [ln for ln in f.read().splitlines() if not ln.lstrip().startswith(COMMENT_PREFIXES)]
        except OSError:
            return []

    def tokens(self, path: str, default_label: str) -> List[Tuple[str, str]]:
        """(label, token) for every line that sets the token variable."""
        found = []
        for line in self.lines(path):
            i = line.find(TOKEN_VAR)
            if i < 0:
                continue
            # Keep the rest of the line: a $(cat ...) path may contain spaces.
            token = self.token_from_value(line[i + len(TOKEN_VAR):])
            if token:
                found.append((self.command_name(line) or default_label, token))
        return found

    def config_dirs(self, path: str) -> List[str]:
        """Directories assigned to CLAUDE_CONFIG_DIR, e.g. alias claude-work='CLAUDE_CONFIG_DIR=~/.claude-work claude'."""
        dirs = []
        for line in self.lines(path):
            for m in re.finditer(CONFIG_DIR_VAR + r"[\"']?\s*=\s*([\"']?)([^\"'\s;]+)\1", line):
                dirs.append(expand_path(m.group(2), self.home))
        return dirs

    @staticmethod
    def command_name(line: str) -> Optional[str]:
        for rx in NAME_RES:
            m = rx.match(line)
            if m:
                return m.group(1)
        return None


# ---------- claude_usage/sources.py ----------

"""Account sources. Each one finds a single kind of account; AccountRegistry merges them."""


import glob
import json
import os
import re
import stat
import subprocess
from dataclasses import dataclass
from typing import Callable, Iterable, List, Optional, Sequence, Tuple


POSIX_RC_FILES = (".zshrc", ".zprofile", ".zshenv", ".bashrc", ".bash_profile", ".profile")
WINDOWS_RC_FILES = POSIX_RC_FILES + tuple(
    os.path.join(docs, shell, profile)
    for docs in ("Documents", os.path.join("OneDrive", "Documents"))
    for shell in ("PowerShell", "WindowsPowerShell")
    for profile in ("Microsoft.PowerShell_profile.ps1", "profile.ps1")
)
SCRIPT_DIRS = ("bin", os.path.join(".local", "bin"))
WINDOWS_SCRIPT_EXTS = ("", ".ps1", ".cmd", ".bat", ".sh")
CREDENTIALS_FILE = ".credentials.json"


# ---------- user config ----------

@dataclass(frozen=True)
class UserConfig:
    """~/.config/claude-usage.conf, one entry per line:
        label = /path/to/token-file     add a token the scan cannot find
        keychain = off                  hide browser logins (keychain and credentials files)
    """
    token_files: Tuple[Tuple[str, str], ...] = ()
    show_logins: bool = True

    @classmethod
    def load(cls, path: str, home: str) -> UserConfig:
        token_files, show_logins = [], True
        try:
            with open(path, encoding="utf-8", errors="ignore") as f:
                lines = f.read().splitlines()
        except OSError:
            return cls()
        for line in lines:
            line = line.split("#", 1)[0].strip()
            if "=" not in line:
                continue
            key, val = (s.strip() for s in line.split("=", 1))
            if key in ("keychain", "logins"):
                show_logins = val.lower() not in ("off", "no", "false", "0")
            elif val:
                token_files.append((key, expand_path(val, home)))
        return cls(tuple(token_files), show_logins)


# ---------- macOS keychain ----------

class Keychain:
    """The macOS login keychain, through /usr/bin/security."""

    def __init__(self, security: str = "/usr/bin/security", run=subprocess.run):
        self._security = security
        self._run = run

    def services(self, prefix: str) -> List[str]:
        out = self._run([self._security, "dump-keychain"], capture_output=True, text=True,
                        timeout=15).stdout
        names = set(re.findall(r'"svce"<blob>="(%s[^"]*)"' % re.escape(prefix), out))
        return sorted(names, key=lambda s: (s != prefix, s))

    def password(self, service: str) -> str:
        return self._run([self._security, "find-generic-password", "-s", service, "-w"],
                         capture_output=True, text=True, timeout=10).stdout


class KeychainAccount(Account):
    is_login = True

    def __init__(self, service: str, keychain: Keychain):
        suffix = service[len(KEYCHAIN_SERVICE):].strip("-")
        super().__init__("claude (%s)" % suffix if suffix else "claude")
        self.service = service
        self._keychain = keychain

    @property
    def identity(self) -> str:
        return self.service

    def token(self) -> str:
        return json.loads(self._keychain.password(self.service))["claudeAiOauth"]["accessToken"]


class KeychainSource:
    def __init__(self, keychain: Keychain):
        self._keychain = keychain

    def accounts(self) -> List[Account]:
        return [KeychainAccount(s, self._keychain) for s in self._keychain.services(KEYCHAIN_SERVICE)]


# ---------- credentials files (Linux, Windows, macOS fallback) ----------

def config_dir_label(directory: str) -> str:
    """~/.claude -> "claude", ~/.claude-work -> "claude (work)"."""
    name = os.path.basename(os.path.normpath(directory)).lstrip(".")
    rest = re.sub(r"^claude[-_.]?", "", name, flags=re.I)
    if not rest:
        return "claude"
    return "claude (%s)" % rest if name.lower().startswith("claude") else name


class CredentialsFileAccount(Account):
    """A browser login stored in <config dir>/.credentials.json."""
    is_login = True

    def __init__(self, path: str, clock: Clock):
        super().__init__(config_dir_label(os.path.dirname(path)))
        self.path = path
        self._clock = clock

    @property
    def identity(self) -> str:
        return os.path.normcase(os.path.realpath(self.path))

    def oauth(self) -> dict:
        with open(self.path, encoding="utf-8") as f:
            return json.load(f)["claudeAiOauth"]

    def expired(self) -> bool:
        expires_ms = self.oauth().get("expiresAt") or 0
        return bool(expires_ms) and expires_ms / 1000 < self._clock.now()

    def token(self) -> str:
        if self.expired():
            raise LoginExpired("đăng nhập đã hết hạn, mở `claude` một lần để làm mới")
        return self.oauth()["accessToken"]


class CredentialsFileSource:
    """Every config dir that holds a .credentials.json.

    skip_expired: on macOS the keychain is the real store and the file is a fallback that is
    often left behind expired, so expired files are hidden there.
    """

    def __init__(self, config_dirs: Callable[[], Iterable[str]], clock: Clock, skip_expired: bool):
        self._config_dirs = config_dirs
        self._clock = clock
        self._skip_expired = skip_expired

    def accounts(self) -> List[Account]:
        result: List[Account] = []
        for d in self._config_dirs():
            path = os.path.join(d, CREDENTIALS_FILE)
            if not os.path.isfile(path):
                continue
            acc = CredentialsFileAccount(path, self._clock)
            try:
                if self._skip_expired and acc.expired():
                    continue
            except (OSError, ValueError, KeyError, TypeError):
                continue
            result.append(acc)
        return result


class ConfigDirFinder:
    """Candidate Claude config dirs: $CLAUDE_CONFIG_DIR, ~/.claude, ~/.claude-*, and any dir an
    alias or script assigns to CLAUDE_CONFIG_DIR."""

    def __init__(self, home: str, env_dir: Optional[str], scanner: ShellScanner,
                 shell_files: Callable[[], Iterable[Tuple[str, str]]]):
        self._home = home
        self._env_dir = env_dir
        self._scanner = scanner
        self._shell_files = shell_files

    def __call__(self) -> List[str]:
        dirs = [self._env_dir] if self._env_dir else []
        dirs.append(os.path.join(self._home, ".claude"))
        dirs += sorted(glob.glob(os.path.join(self._home, ".claude[-_.]*")))
        for path, _ in self._shell_files():
            dirs += self._scanner.config_dirs(path)
        seen, unique = set(), []
        for d in dirs:
            key = os.path.normcase(os.path.realpath(d))
            if key not in seen:
                seen.add(key)
                unique.append(d)
        return unique


# ---------- setup-tokens ----------

class ShellFiles:
    """(path, default label) of every rc/profile file and script that may set a token."""

    def __init__(self, home: str, rc_files: Sequence[str], is_script: Callable[[str, os.stat_result], bool]):
        self._home = home
        self._rc_files = rc_files
        self._is_script = is_script

    def __call__(self) -> List[Tuple[str, str]]:
        files = [(os.path.join(self._home, rc), os.path.basename(rc)) for rc in self._rc_files]
        for d in SCRIPT_DIRS:
            d = os.path.join(self._home, d)
            try:
                entries = sorted(os.listdir(d))
            except OSError:
                continue
            for e in entries:
                p = os.path.join(d, e)
                try:
                    st = os.stat(p)
                except OSError:
                    continue
                if stat.S_ISREG(st.st_mode) and self._is_script(p, st):
                    files.append((p, e))
        return files


def is_posix_script(path: str, st: os.stat_result) -> bool:
    return bool(st.st_mode & 0o111)


def is_windows_script(path: str, st: os.stat_result) -> bool:
    return os.path.splitext(path)[1].lower() in WINDOWS_SCRIPT_EXTS


class ShellTokenSource:
    def __init__(self, files: Callable[[], Iterable[Tuple[str, str]]], scanner: ShellScanner):
        self._files = files
        self._scanner = scanner

    def accounts(self) -> List[Account]:
        return [TokenAccount(label, token)
                for path, default in self._files()
                for label, token in self._scanner.tokens(path, default)]


class EnvTokenSource:
    """CLAUDE_CODE_OAUTH_TOKEN from the environment or, on Windows, the user's registry."""

    def __init__(self, readers: Sequence[Callable[[], Optional[str]]]):
        self._readers = readers

    def accounts(self) -> List[Account]:
        result: List[Account] = []
        for read in self._readers:
            try:
                value = read()
            except OSError:
                continue
            token = token_in_text(value)
            if token:
                result.append(TokenAccount("env", token))
        return result


def windows_registry_token() -> Optional[str]:
    """HKCU\\Environment\\CLAUDE_CODE_OAUTH_TOKEN, as written by `setx`."""
    import winreg  # Windows only
    try:
        with winreg.OpenKey(winreg.HKEY_CURRENT_USER, "Environment") as key:
            return str(winreg.QueryValueEx(key, "CLAUDE_CODE_OAUTH_TOKEN")[0])
    except FileNotFoundError:
        return None


class ConfTokenSource:
    def __init__(self, config: UserConfig):
        self._config = config

    def accounts(self) -> List[Account]:
        result: List[Account] = []
        for label, path in self._config.token_files:
            token = read_token_file(path)
            if token:
                result.append(TokenAccount(label, token))
        return result


# ---------- registry ----------

class AccountRegistry:
    """All accounts from every source, in source order, without duplicates.
    A source that fails (no keychain, unreadable file) is skipped."""

    def __init__(self, sources: Sequence[AccountSource]):
        self._sources = sources

    def accounts(self) -> List[Account]:
        seen, result = set(), []
        for source in self._sources:
            try:
                found = source.accounts()
            except Exception:
                continue
            for acc in found:
                if acc.identity not in seen:
                    seen.add(acc.identity)
                    result.append(acc)
        return result


# ---------- claude_usage/infra.py ----------

"""Small I/O adapters: HTTP client and JSON file cache."""


import json
import os
import urllib.error
import urllib.request
from dataclasses import dataclass, field
from typing import Any, Dict, Optional, Protocol


@dataclass
class HttpResponse:
    status: int
    headers: Dict[str, str] = field(default_factory=dict)  # lower-case names
    body: bytes = b""

    def json(self) -> Any:
        return json.loads(self.body.decode("utf-8"))


class HttpClient(Protocol):
    def request(self, url: str, method: str = "GET", headers: Optional[Dict[str, str]] = None,
                body: Optional[bytes] = None, timeout: float = 15) -> HttpResponse: ...


class UrllibHttpClient:
    """HttpClient over urllib. An HTTP error status is a response, not an exception;
    network failures still raise (URLError, timeout)."""

    def request(self, url: str, method: str = "GET", headers: Optional[Dict[str, str]] = None,
                body: Optional[bytes] = None, timeout: float = 15) -> HttpResponse:
        req = urllib.request.Request(url, data=body, headers=headers or {}, method=method)
        try:
            with urllib.request.urlopen(req, timeout=timeout) as r:
                return HttpResponse(r.status, _lower_headers(r.headers), r.read())
        except urllib.error.HTTPError as e:
            return HttpResponse(e.code, _lower_headers(e.headers), e.read() or b"")


def _lower_headers(headers) -> Dict[str, str]:
    return {k.lower(): v for k, v in headers.items()} if headers else {}


class JsonCache:
    """Named JSON documents in one directory, with their age."""

    def __init__(self, directory: str, clock: Clock):
        self.directory = directory
        self._clock = clock

    def path(self, name: str) -> str:
        return os.path.join(self.directory, name + ".json")

    def load(self, name: str) -> Any:
        try:
            with open(self.path(name), encoding="utf-8") as f:
                return json.load(f)
        except (OSError, ValueError):
            return None

    def save(self, name: str, data: Any) -> None:
        os.makedirs(self.directory, exist_ok=True)
        tmp = self.path(name) + ".tmp"
        with open(tmp, "w", encoding="utf-8") as f:
            json.dump(data, f)
        os.replace(tmp, self.path(name))

    def age(self, name: str) -> float:
        try:
            return self._clock.now() - os.path.getmtime(self.path(name))
        except OSError:
            return float("inf")

    def fresh(self, name: str, max_age: float) -> Any:
        """The document if it is younger than max_age seconds, else None."""
        return self.load(name) if self.age(name) < max_age else None


# ---------- claude_usage/updater.py ----------

"""Release check and in-place self-update of the single-file plugin."""


import os
import re
from typing import Optional, Tuple


UPDATE_CACHE = "update"
SHEBANG = "#!/usr/bin/python3"


def parse_version(v: str) -> Tuple[int, ...]:
    return tuple(int(x) for x in re.findall(r"\d+", v)[:3])


def is_newer(tag: Optional[str], version: str) -> bool:
    return bool(tag) and parse_version(tag or "") > parse_version(version)


class ReleaseChecker:
    """The newest release tag, asking GitHub at most every max_age seconds."""

    def __init__(self, http: HttpClient, github_api: str, repo: str, cache: JsonCache,
                 max_age: float):
        self._http = http
        self._url = "%s/repos/%s/releases/latest" % (github_api, repo)
        self._cache = cache
        self._max_age = max_age

    def latest(self) -> Optional[str]:
        cached = self._cache.load(UPDATE_CACHE)
        if cached and self._cache.age(UPDATE_CACHE) < self._max_age:
            return cached.get("tag")
        try:
            r = self._http.request(self._url, timeout=10,
                                   headers={"Accept": "application/vnd.github+json"})
            if r.status != 200:
                raise RuntimeError("GitHub HTTP %d" % r.status)
            tag = r.json()["tag_name"]
        except Exception:
            return (cached or {}).get("tag")
        self._cache.save(UPDATE_CACHE, {"tag": tag})
        return tag


class SelfUpdater:
    """Replaces the plugin file with the one from the latest release, after sanity checks.

    Releases from v1.2.x run the same checks on the file they download, so the file at
    plugin_path_in_repo must stay a single self-contained script.
    """

    def __init__(self, http: HttpClient, checker: ReleaseChecker, github_raw: str, repo: str,
                 plugin_path_in_repo: str, version: str, target: str):
        self._http = http
        self._checker = checker
        self._raw = github_raw
        self._repo = repo
        self._path_in_repo = plugin_path_in_repo
        self._version = version
        self._target = target

    def update(self) -> bool:
        """True when the file was replaced."""
        tag = self._checker.latest()
        if not tag or not is_newer(tag, self._version):
            return False
        url = "%s/%s/%s/%s" % (self._raw, self._repo, tag, self._path_in_repo)
        r = self._http.request(url, timeout=30)
        if r.status != 200:
            raise RuntimeError("download HTTP %d" % r.status)
        code = r.body.decode("utf-8")
        want = 'VERSION = "%s"' % ".".join(str(n) for n in parse_version(tag))
        if not code.startswith(SHEBANG) or want not in code:
            raise RuntimeError("downloaded plugin failed sanity check")
        compile(code, "plugin", "exec")
        tmp = self._target + ".new"
        with open(tmp, "w", encoding="utf-8", newline="\n") as f:
            f.write(code)
        os.chmod(tmp, 0o755)
        os.replace(tmp, self._target)
        return True


# ---------- claude_usage/usage.py ----------

"""Reading usage and profile data from the Anthropic API, with caching."""


import json
import re
from typing import Dict, List, Mapping, Optional, Sequence, Tuple


OAUTH_BETA = "oauth-2025-04-20"
RATE_PREFIX = "anthropic-ratelimit-unified-"
PROBE_SYSTEM = "You are Claude Code, Anthropic's official CLI for Claude."


def parse_rate_headers(h: Mapping[str, str], model_windows: Mapping[str, str]) -> Usage:
    """Usage from the anthropic-ratelimit-unified-* headers (names in lower case)."""
    p = RATE_PREFIX
    models: List[ModelWindow] = []
    for name in h:
        m = re.match(re.escape(p) + r"7d_(\w+)-utilization$", name)
        if m:
            suffix = m.group(1)
            models.append(ModelWindow(
                name=model_windows.get(suffix, suffix),
                pct=float(h[name]) * 100,
                reset=int(h.get(p + "7d_" + suffix + "-reset") or 0),
            ))
    return Usage(
        five_hour=float(h[p + "5h-utilization"]) * 100,
        five_hour_reset=int(h[p + "5h-reset"]),
        weekly=float(h[p + "7d-utilization"]) * 100,
        weekly_reset=int(h[p + "7d-reset"]),
        models=tuple(models),
    )


class UsageProbe:
    """Reads usage from the rate-limit headers of a 1-token request.

    /api/oauth/usage is not used: setup-tokens lack the scope for it and it returns 429 for
    long stretches when polled. A Fable request also returns the per-model weekly windows
    (e.g. 7d_oi), which a Haiku one omits, so models are tried in order.
    """

    def __init__(self, http: HttpClient, api: str, models: Sequence[str],
                 model_windows: Mapping[str, str]):
        self._http = http
        self._api = api
        self._models = models
        self._model_windows = model_windows

    def probe(self, token: str) -> Usage:
        for model in self._models:
            body = json.dumps({
                "model": model,
                "max_tokens": 1,
                "system": PROBE_SYSTEM,
                "messages": [{"role": "user", "content": "hi"}],
            }).encode()
            # A rate-limited account (429) still returns the usage headers.
            r = self._http.request(self._api + "/v1/messages", method="POST", body=body, timeout=20,
                                   headers={
                                       "Authorization": "Bearer " + token,
                                       "anthropic-beta": OAUTH_BETA,
                                       "anthropic-version": "2023-06-01",
                                       "content-type": "application/json",
                                   })
            if r.headers.get(RATE_PREFIX + "5h-utilization") is not None:
                return parse_rate_headers(r.headers, self._model_windows)
        raise RuntimeError("no rate-limit headers")


class ProfileClient:
    def __init__(self, http: HttpClient, api: str):
        self._http = http
        self._api = api

    def email(self, token: str) -> str:
        r = self._http.request(self._api + "/api/oauth/profile", timeout=15, headers={
            "Authorization": "Bearer " + token,
            "anthropic-beta": OAUTH_BETA,
        })
        if r.status != 200:
            raise RuntimeError("profile HTTP %d" % r.status)
        return r.json()["account"]["email"]


def describe_error(e: Exception) -> str:
    return "%s: %s" % (type(e).__name__, str(e)[:160])


class UsageService:
    """Usage of an account, probed at most every max_age seconds. On failure it falls back
    to the last good result and reports the error alongside."""

    def __init__(self, probe: UsageProbe, cache: JsonCache, max_age: float):
        self._probe = probe
        self._cache = cache
        self._max_age = max_age

    def usage(self, account: Account, force: bool = False) -> Tuple[Optional[Usage], Optional[str]]:
        key = account.cache_key
        cached = None if force else self._cache.fresh(key, self._max_age)
        if cached:
            return Usage.from_dict(cached), None
        try:
            usage = self._probe.probe(account.token())
        except Exception as e:
            last = self._cache.load(key)
            return (Usage.from_dict(last) if last else None), describe_error(e)
        self._cache.save(key, usage.to_dict())
        return usage, None


class IdentityService:
    """The text shown after an account's label: its email for a login, "token" otherwise."""

    def __init__(self, profile: ProfileClient, cache: JsonCache, max_age: float):
        self._profile = profile
        self._cache = cache
        self._max_age = max_age

    def detail(self, account: Account) -> str:
        if not account.is_login:
            return "token"
        name = account.cache_key + "-email"
        cached: Optional[Dict[str, str]] = self._cache.load(name)
        if cached and self._cache.age(name) < self._max_age:
            return cached.get("email", "")
        try:
            email = self._profile.email(account.token())
        except Exception:
            return (cached or {}).get("email", "")
        self._cache.save(name, {"email": email})
        return email


# ---------- claude_usage/view.py ----------

"""Menu model: what to show, independent of how a frontend draws it."""


import re
from dataclasses import dataclass
from typing import List, Optional, Sequence, Set, Tuple


REFRESH, UPDATE, OPEN, QUIT = "refresh", "update", "open", "quit"
GRAY, GREEN, ORANGE, RED = "gray", "#2e7d32", "orange", "red"


@dataclass(frozen=True)
class Action:
    kind: str       # REFRESH | UPDATE | OPEN | QUIT
    url: str = ""   # for OPEN


@dataclass(frozen=True)
class MenuItem:
    text: str = ""
    color: Optional[str] = None
    size: Optional[int] = None
    action: Optional[Action] = None
    separator: bool = False


SEPARATOR = MenuItem(separator=True)


@dataclass(frozen=True)
class Menu:
    title: str                    # e.g. "C 13/8/1  T 0/65/1"
    title_color: Optional[str]    # ORANGE / RED when a limit is close
    update_available: bool
    worst: Optional[float]        # highest known percentage, None when nothing is known
    items: Tuple[MenuItem, ...]


def short_name(label: str, taken: Set[str]) -> str:
    """One letter per account (C, T, W...), with a digit when letters collide."""
    base = re.sub(r"^claude[-_.]?", "", label, flags=re.I) or label
    s = base[:1].upper() or "?"
    n = 2
    while s in taken:
        s = base[:1].upper() + str(n)
        n += 1
    taken.add(s)
    return s


class Presenter:
    def __init__(self, clock: Clock, version: str, repo_url: str, warn: float, crit: float,
                 max_in_title: int):
        self._clock = clock
        self._version = version
        self._repo_url = repo_url
        self._warn = warn
        self._crit = crit
        self._max_in_title = max_in_title

    def color(self, pct: float) -> Optional[str]:
        return RED if pct >= self._crit else ORANGE if pct >= self._warn else None

    def time_left(self, epoch: int) -> str:
        """Time left until a reset, e.g. "sau 2 giờ 15 phút". Frontends redraw every
        minute, so the countdown stays current between probes."""
        mins = -(-(epoch - int(self._clock.now())) // 60)  # round up: never "0 phút" early
        if mins <= 0:
            return "ngay bây giờ"
        days, rest = divmod(mins, 1440)
        hours, mins = divmod(rest, 60)
        if days:
            parts = [(days, "ngày"), (hours, "giờ")]
        elif hours:
            parts = [(hours, "giờ"), (mins, "phút")]
        else:
            parts = [(mins, "phút")]
        return "sau " + " ".join("%d %s" % (n, u) for n, u in parts if n)

    def update_items(self, tag: Optional[str]) -> List[MenuItem]:
        if not tag:
            return []
        return [
            MenuItem("Có bản mới %s (đang dùng v%s)" % (tag, self._version), color=GREEN),
            MenuItem("Cập nhật ngay", action=Action(UPDATE)),
            MenuItem("Xem thay đổi", action=Action(OPEN, "%s/releases/tag/%s" % (self._repo_url, tag))),
            SEPARATOR,
        ]

    def present(self, rows: Sequence[AccountRow], new_tag: Optional[str]) -> Menu:
        """new_tag: the newer release to offer, or None."""
        update = self.update_items(new_tag)
        if not rows:
            return Menu("Claude ?", None, bool(new_tag), None, tuple(update + [
                MenuItem("Không tìm thấy tài khoản Claude Code nào"),
                MenuItem("Đăng nhập bằng `claude`, hoặc khai báo token trong ~/.config/claude-usage.conf",
                         size=11),
            ]))

        known = [r.usage for r in rows if r.usage]
        worst = max([max(u.percentages()) for u in known] or [0])
        if len(rows) <= self._max_in_title:
            title = "  ".join(
                "%s %s" % (r.short, "/".join("%d" % round(x) for x in r.usage.percentages()))
                if r.usage else r.short + " ?"
                for r in rows)
        else:
            title = "Claude %d%%" % round(worst)

        items = list(update)
        for r in rows:
            items += self.account_items(r)
        items += [
            MenuItem("Cập nhật mỗi 3 phút", color=GRAY, size=11),
            MenuItem("Thứ tự số: % giới hạn 5 giờ / tuần / Fable tuần", color=GRAY, size=11),
            MenuItem("Phiên bản v%s" % self._version, color=GRAY, size=11,
                     action=Action(OPEN, self._repo_url)),
            MenuItem("Ủng hộ tác giả", action=Action(OPEN, self._repo_url + "#support")),
            MenuItem("Làm mới ngay", action=Action(REFRESH)),
        ]
        return Menu(title, self.color(worst), bool(new_tag), worst if known else None, tuple(items))

    def account_items(self, r: AccountRow) -> List[MenuItem]:
        head = "%s: %s" % (r.short, r.label)
        if r.detail:
            head += " - " + r.detail
        items = [MenuItem(head, size=13)]
        u = r.usage
        if u is None:
            items.append(MenuItem("Không đọc được hạn mức", color=GRAY))
        else:
            for name, pct, reset in (("5 giờ", u.five_hour, u.five_hour_reset),
                                     ("Tuần", u.weekly, u.weekly_reset)):
                items.append(MenuItem("%s: %d%%  (reset %s)" % (name, round(pct), self.time_left(reset)),
                                      color=self.color(pct)))
            for m in u.models:
                text = "%s (tuần): %d%%" % (m.name, round(m.pct))
                if m.reset:
                    text += "  (reset %s)" % self.time_left(m.reset)
                items.append(MenuItem(text, color=self.color(m.pct)))
            if r.error:
                items.append(MenuItem("Số liệu cũ, lần cập nhật vừa rồi bị lỗi", color=GRAY, size=11))
        if r.error:
            items.append(MenuItem("Lỗi: %s" % r.error, color=GRAY, size=11))
        items.append(SEPARATOR)
        return items


# ---------- claude_usage/app.py ----------

"""Use cases: build the menu, refresh every account. Frontends depend on this, not on I/O."""


import os
import sys
import time
from concurrent.futures import ThreadPoolExecutor
from typing import Callable, Iterable, List, Optional, Sequence, TypeVar


T = TypeVar("T")
R = TypeVar("R")
MAX_PARALLEL_PROBES = 16


def map_parallel(fn: Callable[[T], R], items: Iterable[T]) -> List[R]:
    """fn over items on a thread pool, results in input order. Each account's probe is one
    blocking HTTP call, so ten accounts take about as long as one."""
    items = list(items)
    if len(items) <= 1:
        return [fn(x) for x in items]
    with ThreadPoolExecutor(max_workers=min(MAX_PARALLEL_PROBES, len(items))) as pool:
        return list(pool.map(fn, items))


class RunLog:
    """Keeps the last run's errors on disk so a blank menu can be diagnosed."""

    def __init__(self, directory: str, clock: Clock, version: str):
        self.path = os.path.join(directory, "last-run.log")
        self._clock = clock
        self._version = version

    def write(self, rows: Sequence[AccountRow]) -> None:
        try:
            os.makedirs(os.path.dirname(self.path), exist_ok=True)
            with open(self.path, "w", encoding="utf-8") as f:
                stamp = time.strftime("%Y-%m-%d %H:%M:%S", time.localtime(self._clock.now()))
                f.write("%s v%s python=%s\n" % (stamp, self._version, sys.executable))
                for r in rows:
                    f.write("%s %s: %s\n" % (r.short, r.label, r.error or "ok"))
        except OSError:
            pass


class UsageApp:
    def __init__(self, registry: AccountRegistry, usage: UsageService, identity: IdentityService,
                 releases: ReleaseChecker, presenter: Presenter, run_log: RunLog, version: str,
                 mapper: Callable[[Callable, Iterable], List] = map_parallel):
        self._map = mapper
        self._registry = registry
        self._usage = usage
        self._identity = identity
        self._releases = releases
        self._presenter = presenter
        self._run_log = run_log
        self._version = version

    def rows(self, force: bool = False) -> List[AccountRow]:
        accounts = self._registry.accounts()

        def read(acc):
            usage, error = self._usage.usage(acc, force=force)
            return usage, error, self._identity.detail(acc)

        taken: set = set()
        return [AccountRow(short_name(acc.label, taken), acc.label, detail, usage, error)
                for acc, (usage, error, detail) in zip(accounts, self._map(read, accounts))]

    def menu(self, force: bool = False) -> Menu:
        tag = self._releases.latest()
        rows = self.rows(force=force)
        if rows:
            self._run_log.write(rows)
        return self._presenter.present(rows, tag if is_newer(tag, self._version) else None)

    def refresh(self) -> None:
        """Probe every account now, ignoring the cache."""
        self._map(lambda acc: self._usage.usage(acc, force=True), self._registry.accounts())

    def newer_release(self) -> Optional[str]:
        tag = self._releases.latest()
        return tag if is_newer(tag, self._version) else None


# ---------- claude_usage/platform_setup.py ----------

"""Composition root: the only place that knows which adapters each OS gets."""


import os
import sys
from dataclasses import dataclass
from typing import List, Mapping


MACOS, LINUX, WINDOWS = "macos", "linux", "windows"


def detect_os(platform: str = sys.platform) -> str:
    if platform == "darwin":
        return MACOS
    if platform.startswith("win"):
        return WINDOWS
    return LINUX


@dataclass(frozen=True)
class Host:
    os_name: str               # MACOS | LINUX | WINDOWS
    home: str
    env: Mapping[str, str]
    self_path: str             # the plugin file itself

    @classmethod
    def current(cls) -> Host:
        env = os.environ
        os_name = detect_os()
        home = env.get("USERPROFILE") if os_name == WINDOWS and env.get("USERPROFILE") else env.get("HOME")
        return cls(os_name, home or os.path.expanduser("~"), env, os.path.realpath(sys.argv[0]))

    @property
    def cache_dir(self) -> str:
        return os.path.join(self.home, ".cache", "claude-usage")

    @property
    def conf_path(self) -> str:
        return os.path.join(self.home, ".config", "claude-usage.conf")


def build_sources(host: Host, config: UserConfig, clock: Clock) -> List[AccountSource]:
    scanner = ShellScanner(host.home)
    if host.os_name == WINDOWS:
        files = ShellFiles(host.home, WINDOWS_RC_FILES, is_windows_script)
        env_readers = [lambda: host.env.get("CLAUDE_CODE_OAUTH_TOKEN"), windows_registry_token]
    else:
        files = ShellFiles(host.home, POSIX_RC_FILES, is_posix_script)
        env_readers = [lambda: host.env.get("CLAUDE_CODE_OAUTH_TOKEN")]

    sources: List[AccountSource] = []
    if config.show_logins:
        if host.os_name == MACOS:
            sources.append(KeychainSource(Keychain()))
        dirs = ConfigDirFinder(host.home, host.env.get("CLAUDE_CONFIG_DIR"), scanner, files)
        sources.append(CredentialsFileSource(dirs, clock, skip_expired=host.os_name == MACOS))
    sources += [ShellTokenSource(files, scanner), EnvTokenSource(env_readers),
                ConfTokenSource(config)]
    return sources


@dataclass
class Services:
    app: UsageApp
    updater: SelfUpdater


def build(host: Host, clock: Clock = None, http: HttpClient = None) -> Services:
    clock = clock or SystemClock()
    http = http or UrllibHttpClient()
    endpoints = Endpoints.from_env(host.env)
    cache = JsonCache(host.cache_dir, clock)
    config = UserConfig.load(host.conf_path, host.home)
    releases = ReleaseChecker(http, endpoints.github_api, REPO, cache, UPDATE_EVERY)
    app = UsageApp(
        registry=AccountRegistry(build_sources(host, config, clock)),
        usage=UsageService(UsageProbe(http, endpoints.api, PROBE_MODELS, MODEL_WINDOWS), cache,
                           PROBE_EVERY),
        identity=IdentityService(ProfileClient(http, endpoints.api), cache, EMAIL_EVERY),
        releases=releases,
        presenter=Presenter(clock, VERSION, REPO_URL, WARN_PCT, CRIT_PCT, MAX_IN_TITLE),
        run_log=RunLog(host.cache_dir, clock, VERSION),
        version=VERSION,
    )
    updater = SelfUpdater(http, releases, endpoints.github_raw, REPO, PLUGIN_PATH_IN_REPO, VERSION,
                          host.self_path)
    return Services(app, updater)


# ---------- claude_usage/tray.py ----------

"""Long-running tray frontend (Windows, Linux desktops without Argos).

TrayController owns the behaviour (when to refresh, what each action does); a TrayBackend only
draws a Menu and reports clicks, so each OS needs nothing but a small backend.
"""


import os
import subprocess
import sys
import threading
import webbrowser
from abc import ABC, abstractmethod
from typing import Callable, List, Optional, Sequence


TRAY_REFRESH_SECONDS = 60
QUIT_ITEM = MenuItem("Thoát", action=Action(QUIT))


class TrayBackend(ABC):
    """A native tray icon. All methods except call_soon are called on the UI thread."""

    @abstractmethod
    def run(self, on_start: Callable[[], None]) -> None:
        """Create the icon, call on_start on the UI thread, then block in the UI loop."""

    @abstractmethod
    def show(self, menu: Menu) -> None:
        """Replace the icon text/tooltip and the menu. Clicking an item with an action must
        call the handler given to set_action_handler with that Action."""

    @abstractmethod
    def set_action_handler(self, handler: Callable[[Action], None]) -> None: ...

    @abstractmethod
    def call_soon(self, fn: Callable[[], None]) -> None:
        """Run fn on the UI thread. Safe to call from any thread."""

    @abstractmethod
    def every(self, seconds: int, fn: Callable[[], None]) -> None:
        """Call fn on the UI thread every `seconds`."""

    @abstractmethod
    def quit(self) -> None: ...


class TrayController:
    """Refreshes the tray every minute and runs menu actions.

    Network work happens on a worker thread; results go back to the UI thread through
    backend.call_soon, so a slow probe never freezes the icon.
    """

    def __init__(self, backend: TrayBackend, build_menu: Callable[[bool], Menu],
                 refresh: Callable[[], None], update: Callable[[], bool],
                 restart: Callable[[], None], open_url: Callable[[str], object] = webbrowser.open,
                 spawn: Callable[[Callable[[], None]], None] = None):
        self._backend = backend
        self._build_menu = build_menu
        self._refresh = refresh
        self._update = update
        self._restart = restart
        self._open_url = open_url
        self._spawn = spawn or _start_daemon_thread
        self._busy = threading.Lock()

    def run(self) -> None:
        self._backend.set_action_handler(self.on_action)
        self._backend.run(self.start)

    def start(self) -> None:
        self._backend.show(loading_menu())
        self._backend.every(TRAY_REFRESH_SECONDS, self.reload)
        self.reload()

    def reload(self, force: bool = False) -> None:
        """Rebuild the menu in the background; skip if a rebuild is already running."""
        if not self._busy.acquire(blocking=False):
            return

        def work():
            try:
                if force:
                    self._refresh()
                menu = with_quit(self._build_menu(False))
            except Exception as e:  # keep the icon alive whatever happens
                menu = error_menu(e)
            finally:
                self._busy.release()
            self._backend.call_soon(lambda: self._backend.show(menu))

        self._spawn(work)

    def on_action(self, action: Action) -> None:
        if action.kind == REFRESH:
            self.reload(force=True)
        elif action.kind == OPEN:
            self._open_url(action.url)
        elif action.kind == UPDATE:
            self._spawn(self._do_update)
        elif action.kind == QUIT:
            self._backend.quit()

    def _do_update(self) -> None:
        try:
            replaced = self._update()
        except Exception as e:
            self._backend.call_soon(lambda: self._backend.show(error_menu(e)))
            return
        if replaced:
            self._backend.call_soon(self._restart_now)
        else:
            self.reload()

    def _restart_now(self) -> None:
        self._restart()
        self._backend.quit()


def _start_daemon_thread(fn: Callable[[], None]) -> None:
    threading.Thread(target=fn, daemon=True).start()


def with_quit(menu: Menu) -> Menu:
    return Menu(menu.title, menu.title_color, menu.update_available, menu.worst,
                menu.items + (SEPARATOR, QUIT_ITEM))


def loading_menu() -> Menu:
    return Menu("Claude ...", None, False, None, (MenuItem("Đang đọc hạn mức..."), SEPARATOR, QUIT_ITEM))


def error_menu(e: Exception) -> Menu:
    return Menu("Claude ?", None, False, None, (
        MenuItem("Lỗi: %s: %s" % (type(e).__name__, str(e)[:160]), color="gray"),
        MenuItem("Làm mới ngay", action=Action(REFRESH)),
        SEPARATOR, QUIT_ITEM))


def relaunch_command(argv: Sequence[str], executable: str) -> List[str]:
    """The command that starts this tray again, e.g. after a self-update."""
    return [executable, os.path.realpath(argv[0])] + list(argv[1:])


def relaunch(argv: Optional[Sequence[str]] = None, executable: Optional[str] = None) -> None:
    cmd = relaunch_command(argv or sys.argv, executable or sys.executable)
    kwargs = {}
    if os.name == "nt":
        kwargs["creationflags"] = 0x00000008 | 0x00000200  # DETACHED_PROCESS | NEW_PROCESS_GROUP
    else:
        kwargs["start_new_session"] = True
    subprocess.Popen(cmd, close_fds=True, **kwargs)


# ---------- claude_usage/xbar.py ----------

"""Text output for SwiftBar (macOS) and Argos (GNOME), both BitBar-compatible."""


from typing import List


SWIFTBAR, ARGOS = "swiftbar", "argos"
CLI_FLAGS = {REFRESH: "--force", UPDATE: "--update"}


class XbarRenderer:
    """Renders a Menu as BitBar plugin output.

    self_path is the plugin file, which the menu runs again for its refresh and update items.
    """

    def __init__(self, self_path: str, flavor: str = SWIFTBAR):
        self._self_path = self_path
        self._flavor = flavor

    def render(self, menu: Menu) -> str:
        lines = [self.title(menu), "---"]
        for item in menu.items:
            if item.action and item.action.kind == QUIT:
                continue  # the host app has its own quit
            lines.append("---" if item.separator else self.item(item))
        return "\n".join(lines) + "\n"

    def title(self, menu: Menu) -> str:
        line = menu.title + " |"
        if menu.title_color:
            line += " color=" + menu.title_color
        if self._flavor == ARGOS:
            if menu.update_available:
                line += " iconName=software-update-available-symbolic"
            line += " dropdown=false"  # Argos repeats button lines in the menu otherwise
        elif menu.update_available:
            line += " sfimage=arrow.down.circle"
        return line

    def item(self, item: MenuItem) -> str:
        params: List[str] = []
        if item.color:
            params.append("color=" + item.color)
        if item.size:
            params.append("size=%d" % item.size)
        a = item.action
        if a and a.kind == OPEN:
            params.append("href=" + a.url)
        elif a and a.kind in CLI_FLAGS:
            params.append('bash="%s" param1=%s terminal=false refresh=true'
                          % (self._self_path, CLI_FLAGS[a.kind]))
        text = item.text.replace("|", "/")
        return text + (" | " + " ".join(params) if params else "")


# ---------- claude_usage/cli.py ----------

"""Entry point. Without arguments it prints BitBar output (SwiftBar, Argos)."""


import sys
from typing import List, Optional


USAGE = """usage: claude-usage [--force | --update | --tray]
  (none)    print the menu for SwiftBar (macOS) or Argos (GNOME)
  --force   probe every account now, ignoring the cache
  --update  install the latest release over this file
  --tray    run as a tray icon (Windows, Linux desktops without Argos)"""


def tray_backend(os_name: str) -> TrayBackend:
    if os_name == WINDOWS:
        pass
        return Win32TrayBackend()
    if os_name == LINUX:
        pass
        return GtkTrayBackend()
    raise SystemExit("--tray is for Windows and Linux; on macOS use SwiftBar")


def main(argv: Optional[List[str]] = None) -> int:
    args = sys.argv[1:] if argv is None else argv
    host = Host.current()
    services = build(host)
    if args == ["--update"]:
        services.updater.update()
    elif args == ["--force"]:
        services.app.refresh()
    elif args == ["--tray"]:
        TrayController(
            backend=tray_backend(host.os_name),
            build_menu=lambda force: services.app.menu(force=force),
            refresh=services.app.refresh,
            update=services.updater.update,
            restart=relaunch,
        ).run()
    elif not args:
        flavor = ARGOS if "ARGOS_MENU_OPEN" in host.env else SWIFTBAR
        sys.stdout.write(XbarRenderer(host.self_path, flavor).render(services.app.menu()))
    else:
        print(USAGE, file=sys.stderr)
        return 2
    return 0


if __name__ == "__main__":
    import sys
    sys.exit(main())
